//! Independent verification entry point.
//!
//! `cargo run --bin verify`
//!
//! It builds a synthetic fixture specifically aimed at the four trap areas
//! (NULL crossings, all-UNKNOWN predicates, a non-multiple-of-8 universe,
//! versioned deletes) and checks the bitmap engine against an INDEPENDENT
//! row-by-row scalar 3VL oracle. The oracle is implemented here from raw
//! `Option<T>` values with Kleene truth tables — it never calls into
//! `TriSet`/`Bitmap` — so expected answers are not generated by the code under
//! test.
//!
//! Every alive row must be classified as exactly one of TRUE/FALSE/UNKNOWN;
//! every deleted row must be in none. Concrete results AND concrete failure
//! categories are asserted. Logs carry a run id, table version, per-step
//! cardinalities and the judgment basis.

use std::process::ExitCode;

use serde_json::{json, Value};
use tracing::{info, warn};
use tribool_index::batch::{ColumnSpec, ColumnType};
use tribool_index::error::ErrorKind;
use tribool_index::logic::Tri3;
use tribool_index::query::Expr;
use tribool_index::state::Catalog;

/// 13 rows -> non-multiple-of-8 universe (tail byte has 5 invalid bits).
const FIXTURE: &[(&str, Option<i64>, &str)] = &[
    // (city, age, active-as-string) ; active "n" = NULL
    ("Beijing", Some(25), "true"),
    ("Beijing", None, "false"),  // age NULL crossing
    ("Shanghai", Some(40), "n"), // active NULL crossing
    ("Beijing", Some(17), "true"),
    ("Guangzhou", Some(40), "false"),
    ("Beijing", None, "n"), // both NULL -> all-unknown leaf mixes
    ("Shanghai", Some(65), "true"),
    ("Beijing", Some(40), "true"),
    ("Guangzhou", Some(15), "n"),
    ("Shanghai", None, "true"),
    ("Beijing", Some(40), "false"),
    ("Guangzhou", Some(40), "n"),
    ("Beijing", Some(72), "false"),
];

#[derive(Clone)]
struct Row {
    city: Option<String>,
    age: Option<i64>,
    active: Option<bool>,
}

/// Independent scalar truth value (separate enum from the crate's Tri3 on
/// purpose, so the oracle cannot accidentally share implementation).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Scalar {
    T,
    F,
    U,
}

fn s_not(a: Scalar) -> Scalar {
    match a {
        Scalar::T => Scalar::F,
        Scalar::F => Scalar::T,
        Scalar::U => Scalar::U,
    }
}
fn s_and(a: Scalar, b: Scalar) -> Scalar {
    match (a, b) {
        (Scalar::T, Scalar::T) => Scalar::T,
        (Scalar::F, _) | (_, Scalar::F) => Scalar::F,
        _ => Scalar::U,
    }
}
fn s_or(a: Scalar, b: Scalar) -> Scalar {
    match (a, b) {
        (Scalar::F, Scalar::F) => Scalar::F,
        (Scalar::T, _) | (_, Scalar::T) => Scalar::T,
        _ => Scalar::U,
    }
}

/// Scalar comparison written straight from SQL semantics; no bitmap code.
fn cmp_age(op: &str, a: Option<i64>, b: i64) -> Scalar {
    match a {
        None => Scalar::U,
        Some(v) => {
            let bv = match op {
                "=" => v == b,
                "!=" => v != b,
                "<" => v < b,
                "<=" => v <= b,
                ">" => v > b,
                ">=" => v >= b,
                other => panic!("oracle: unknown cmp {other}"),
            };
            if bv {
                Scalar::T
            } else {
                Scalar::F
            }
        }
    }
}

fn cmp_city(a: Option<&str>, b: &str) -> Scalar {
    match a {
        None => Scalar::U,
        Some(v) => {
            if v == b {
                Scalar::T
            } else {
                Scalar::F
            }
        }
    }
}

fn cmp_active(a: Option<bool>, b: bool) -> Scalar {
    match a {
        None => Scalar::U,
        Some(v) => {
            if v == b {
                Scalar::T
            } else {
                Scalar::F
            }
        }
    }
}

/// Recursively evaluate the SAME expression AST the engine uses, but scalar
/// and fully independently.
fn oracle(expr: &Expr, row: &Row) -> Scalar {
    match expr {
        Expr::Cmp { column, cmp, value } => {
            let lit = value.as_ref();
            match (column.as_str(), cmp.as_str()) {
                // IS [NOT] NULL must be dispatched before the typed comparisons,
                // which take a literal.
                ("age", "is_null") | ("city", "is_null") | ("active", "is_null") => {
                    let is_null = match column.as_str() {
                        "age" => row.age.is_none(),
                        "city" => row.city.is_none(),
                        "active" => row.active.is_none(),
                        _ => unreachable!(),
                    };
                    if is_null {
                        Scalar::T
                    } else {
                        Scalar::F
                    }
                }
                ("age", "is_not_null") | ("city", "is_not_null") | ("active", "is_not_null") => {
                    let not_null = match column.as_str() {
                        "age" => row.age.is_some(),
                        "city" => row.city.is_some(),
                        "active" => row.active.is_some(),
                        _ => unreachable!(),
                    };
                    if not_null {
                        Scalar::T
                    } else {
                        Scalar::F
                    }
                }
                ("age", op) => {
                    let n = lit
                        .and_then(|l| match l {
                            tribool_index::index::Literal::Int(n) => Some(*n),
                            _ => None,
                        })
                        .expect("oracle: age needs int literal");
                    cmp_age(op, row.age, n)
                }
                ("city", "=") => {
                    let s = lit
                        .and_then(|l| match l {
                            tribool_index::index::Literal::Text(s) => Some(s.as_str()),
                            _ => None,
                        })
                        .expect("oracle: city needs text literal");
                    cmp_city(row.city.as_deref(), s)
                }
                ("active", "=") => {
                    let b = lit
                        .and_then(|l| match l {
                            tribool_index::index::Literal::Bool(b) => Some(*b),
                            _ => None,
                        })
                        .expect("oracle: active needs bool literal");
                    cmp_active(row.active, b)
                }
                (c, o) => panic!("oracle: unsupported {c} {o}"),
            }
        }
        Expr::Not { arg } => s_not(oracle(arg, row)),
        Expr::And { args } => args.iter().map(|a| oracle(a, row)).fold(Scalar::T, s_and),
        Expr::Or { args } => args.iter().map(|a| oracle(a, row)).fold(Scalar::F, s_or),
    }
}

fn fixture_rows() -> Vec<Row> {
    FIXTURE
        .iter()
        .map(|(city, age, active)| Row {
            city: Some((*city).to_string()),
            age: *age,
            active: match *active {
                "true" => Some(true),
                "false" => Some(false),
                _ => None,
            },
        })
        .collect()
}

fn fixture_json() -> Vec<serde_json::Map<String, Value>> {
    fixture_rows()
        .iter()
        .map(|r| {
            let mut m = serde_json::Map::new();
            m.insert(
                "city".into(),
                r.city.clone().map(Value::String).unwrap_or(Value::Null),
            );
            m.insert("age".into(), r.age.map(Value::from).unwrap_or(Value::Null));
            m.insert(
                "active".into(),
                r.active.map(Value::Bool).unwrap_or(Value::Null),
            );
            m
        })
        .collect()
}

fn spec() -> Vec<ColumnSpec> {
    vec![
        ColumnSpec {
            name: "city".into(),
            col_type: ColumnType::Text,
        },
        ColumnSpec {
            name: "age".into(),
            col_type: ColumnType::Int,
        },
        ColumnSpec {
            name: "active".into(),
            col_type: ColumnType::Bool,
        },
    ]
}

struct Check {
    name: String,
    expr: Expr,
}

fn checks() -> Vec<Check> {
    use Expr::*;
    let leaf_age = |cmp: &str, v: i64| Cmp {
        column: "age".into(),
        cmp: cmp.into(),
        value: Some(tribool_index::index::Literal::Int(v)),
    };
    let leaf_city = |v: &str| Cmp {
        column: "city".into(),
        cmp: "=".into(),
        value: Some(tribool_index::index::Literal::Text(v.into())),
    };
    let leaf_active = |v: bool| Cmp {
        column: "active".into(),
        cmp: "=".into(),
        value: Some(tribool_index::index::Literal::Bool(v)),
    };
    let age_null = Cmp {
        column: "age".into(),
        cmp: "is_null".into(),
        value: None,
    };
    vec![
        Check {
            name: "equality-with-null-crossings".into(),
            expr: leaf_age("=", 40),
        },
        Check {
            // NOT must not word-flip: rows 1,5,9 (NULL age) stay UNKNOWN.
            name: "not-equality".into(),
            expr: Not {
                arg: Box::new(leaf_age("=", 40)),
            },
        },
        Check {
            name: "range-gte".into(),
            expr: leaf_age(">=", 40),
        },
        Check {
            name: "and-null-crossing".into(),
            // age >= 18 AND active = true : row 2 active NULL + age T -> UNKNOWN
            expr: And {
                args: vec![leaf_age(">=", 18), leaf_active(true)],
            },
        },
        Check {
            name: "or-null-crossing".into(),
            // city = Beijing OR active = false
            expr: Or {
                args: vec![leaf_city("Beijing"), leaf_active(false)],
            },
        },
        Check {
            name: "not-and-demorgan-shape".into(),
            expr: Not {
                arg: Box::new(And {
                    args: vec![leaf_age("<", 60), leaf_city("Beijing")],
                }),
            },
        },
        Check {
            name: "is-null-disjunction".into(),
            expr: Or {
                args: vec![age_null.clone(), leaf_age("=", 25)],
            },
        },
        Check {
            // Every age is nullable; compare column whose every value is NULL
            // is emulated by is_null chain; this check covers a leaf that is
            // all-UNKNOWN: city is never NULL here, so use age=40 on NULL rows
            // combined so a sub-expression is fully unknown for some rows.
            name: "nested-not-or".into(),
            expr: And {
                args: vec![
                    Not {
                        arg: Box::new(leaf_active(false)),
                    },
                    Or {
                        args: vec![leaf_age(">", 10), leaf_city("Shanghai")],
                    },
                ],
            },
        },
    ]
}

fn main() -> ExitCode {
    let run_id = format!("verify-{}", uuid::Uuid::new_v4());
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()),
        )
        .init();

    info!(run_id = %run_id, "verification run start: independent scalar oracle vs bitmap engine");

    let mut catalog = Catalog::new();
    let table = catalog
        .create_table("people", spec(), fixture_json())
        .expect("fixture table created");

    let rows = fixture_rows();
    assert_eq!(
        rows.len(),
        13,
        "fixture must be a non-multiple-of-8 universe"
    );

    let mut failures: Vec<String> = Vec::new();

    // ---- Phase 1: no deletes, full non-word-length universe ----
    info!(run_id = %run_id, phase = 1, "phase 1: all 13 rows alive (non-multiple-of-8, tail padding)");
    for check in checks() {
        let version_before = table.read().unwrap().version_info().version;
        let result = {
            let t = table.read().unwrap();
            tribool_index::query::run(&t, &check.expr, &run_id)
        }
        .unwrap_or_else(|e| panic!("check '{}' errored: {e}", check.name));

        for step in &result.trace {
            info!(
                run_id = %run_id, check = %check.name, depth = step.depth,
                expr = %step.expr, t = step.true_rows, f = step.false_rows,
                u = step.unknown_rows, basis = %step.basis,
                "engine step"
            );
        }

        // Exact per-row agreement with the independent oracle.
        for (i, row) in rows.iter().enumerate() {
            let expected = oracle(&check.expr, row);
            let got = result
                .tris
                .state_at(i)
                .expect("alive row must have a state");
            let same = matches!(
                (expected, got),
                (Scalar::T, Tri3::True) | (Scalar::F, Tri3::False) | (Scalar::U, Tri3::Unknown)
            );
            if !same {
                failures.push(format!(
                    "[phase1] check '{}' row {i}: oracle {expected:?} != engine {got:?}",
                    check.name
                ));
            }
        }

        // Partition exhaustiveness: exactly one state per alive row.
        let total =
            result.tris.count_true() + result.tris.count_false() + result.tris.count_unknown();
        if total != rows.len() {
            failures.push(format!(
                "[phase1] check '{}': partition size {total} != universe {}",
                check.name,
                rows.len()
            ));
        }
        if result.version != version_before {
            failures.push(format!(
                "[phase1] check '{}': query bumped version {} -> {}",
                check.name, version_before, result.version
            ));
        }
    }

    // Concrete spot assertions (not just "interface callable").
    {
        let t = table.read().unwrap();
        let eq40 = tribool_index::query::run(
            &t,
            &Expr::Cmp {
                column: "age".into(),
                cmp: "=".into(),
                value: Some(tribool_index::index::Literal::Int(40)),
            },
            &run_id,
        )
        .unwrap();
        let ids = eq40.matched_ids();
        assert_eq!(
            ids,
            vec![2, 4, 7, 10, 11],
            "age=40 rows are 2,4,7,10,11 (rows 1,5,9 NULL -> UNKNOWN)"
        );
        assert_eq!(
            eq40.tris.count_unknown(),
            3,
            "NULL-age rows are UNKNOWN, not FALSE"
        );
        info!(run_id = %run_id, matched = ?ids, unknown = eq40.tris.count_unknown(), "concrete assertion: age = 40");
    }

    // ---- Phase 2: versioned deletes exclude rows from every set ----
    info!(run_id = %run_id, phase = 2, "phase 2: delete rows 3 and 7, expect version bump + exclusion from T/F/U");
    let v1 = table.read().unwrap().version_info();
    assert_eq!(v1.version, 1);
    {
        let mut t = table.write().unwrap();
        let v2 = t.delete_rows(&[3, 7]).expect("delete commits");
        assert_eq!(v2.version, 2, "delete must bump version");
        assert_eq!(v2.deleted_rows, 2);
        assert_eq!(v2.alive_rows, 11);
        // Idempotent repeat delete: no double counting, no extra bump.
        let v2b = t.delete_rows(&[3]).expect("repeat delete is idempotent");
        assert_eq!(
            v2b.version, 2,
            "idempotent delete must not bump version again"
        );
        assert_eq!(v2b.deleted_rows, 2);
    }

    // Capture a TriSet under the v2 alive set, then delete another row to
    // produce an incompatible mode.
    let stale_at_v2 = {
        let t = table.read().unwrap();
        let alive = t.alive();
        t.indexes()
            .get("age")
            .unwrap()
            .evaluate(
                tribool_index::index::CmpOp::Gte,
                Some(&tribool_index::index::Literal::Int(0)),
                &alive,
            )
            .unwrap()
    };
    {
        let mut t = table.write().unwrap();
        let v3 = t.delete_rows(&[0]).expect("second delete commits");
        assert_eq!(v3.version, 3);
        assert_eq!(v3.alive_rows, 10, "13 - 3 deleted");
    }
    {
        let t = table.read().unwrap();
        let fresh = tribool_index::query::run(&t, &checks()[0].expr, &run_id).unwrap();
        // Combining across incompatible delete sets must fail with a concrete
        // category, never silently compute over mixed universes.
        let err = stale_at_v2.and(&fresh.tris).unwrap_err();
        assert_eq!(
            err.kind,
            ErrorKind::DeletesetMismatch,
            "mixed deletion modes must produce DELETESET_MISMATCH, got {:?}",
            err.kind
        );
        let err_or = stale_at_v2.or(&fresh.tris).unwrap_err();
        assert_eq!(err_or.kind, ErrorKind::DeletesetMismatch);
        info!(run_id = %run_id, "concrete assertion: incompatible index modes rejected with DELETESET_MISMATCH");
    }

    // Re-run all checks under v3 (rows 0,3,7 deleted) against oracle, with the
    // alive-only row list.
    for check in checks() {
        let result = {
            let t = table.read().unwrap();
            tribool_index::query::run(&t, &check.expr, &run_id)
        }
        .unwrap();
        let mut classified = 0usize;
        for (i, row) in rows.iter().enumerate() {
            match result.tris.state_at(i) {
                None => {
                    if !matches!(i, 0 | 3 | 7) {
                        failures.push(format!(
                            "[phase2-v3] check '{}': alive row {i} reported deleted",
                            check.name
                        ));
                    }
                }
                Some(got) => {
                    if matches!(i, 0 | 3 | 7) {
                        failures.push(format!(
                            "[phase2-v3] check '{}': deleted row {i} still classified {:?}",
                            check.name, got
                        ));
                    }
                    classified += 1;
                    let expected = oracle(&check.expr, row);
                    let same = matches!(
                        (expected, got),
                        (Scalar::T, Tri3::True)
                            | (Scalar::F, Tri3::False)
                            | (Scalar::U, Tri3::Unknown)
                    );
                    if !same {
                        failures.push(format!(
                            "[phase2-v3] check '{}' row {i}: oracle {expected:?} != engine {got:?}",
                            check.name
                        ));
                    }
                }
            }
        }
        if classified != 10 {
            failures.push(format!(
                "[phase2-v3] check '{}': classified {classified} rows, expected 10 alive",
                check.name
            ));
        }
    }

    // ---- Phase 3: failure categories are concrete ----
    info!(run_id = %run_id, phase = 3, "phase 3: error-path category assertions");
    {
        let t = table.read().unwrap();
        // Universe mismatch: evaluating an index against a wrong-sized alive set.
        let wrong_alive = tribool_index::bits::Bitmap::ones(12);
        let err = t
            .indexes()
            .get("age")
            .unwrap()
            .evaluate(
                tribool_index::index::CmpOp::Eq,
                Some(&tribool_index::index::Literal::Int(1)),
                &wrong_alive,
            )
            .unwrap_err();
        assert_eq!(err.kind, ErrorKind::UniverseMismatch);

        // Type mismatch: int column vs text literal.
        let err = tribool_index::query::run(
            &t,
            &Expr::Cmp {
                column: "age".into(),
                cmp: "=".into(),
                value: Some(tribool_index::index::Literal::Text("x".into())),
            },
            &run_id,
        );
        assert_eq!(err.unwrap_err().kind, ErrorKind::TypeMismatch);

        // Unknown column -> NOT_FOUND.
        let err = tribool_index::query::run(
            &t,
            &Expr::Cmp {
                column: "nope".into(),
                cmp: "=".into(),
                value: Some(tribool_index::index::Literal::Int(1)),
            },
            &run_id,
        );
        assert_eq!(err.unwrap_err().kind, ErrorKind::NotFound);

        // Bad operator -> UNSUPPORTED_OPERATOR.
        let err = tribool_index::index::CmpOp::parse("~~").unwrap_err();
        assert_eq!(err.kind, ErrorKind::UnsupportedOperator);
    }
    {
        let mut t = table.write().unwrap();
        // Out-of-range delete -> INVALID_INPUT, not a silent success.
        let err = t.delete_rows(&[999]).unwrap_err();
        assert_eq!(err.kind, ErrorKind::InvalidInput);
        // Schema-mismatched append (missing/extra-typed column via the batch
        // layer) -> SCHEMA_MISMATCH.
        let mut bad = serde_json::Map::new();
        bad.insert("city".into(), json!("Beijing"));
        bad.insert("age".into(), json!("not-an-int"));
        bad.insert("active".into(), json!(true));
        let err = t.append(std::slice::from_ref(&bad)).unwrap_err();
        assert_eq!(err.kind, ErrorKind::TypeMismatch);
    }
    {
        // Unknown table lives in the catalog layer.
        assert_eq!(
            catalog.table("ghost").unwrap_err().kind,
            ErrorKind::NotFound
        );
    }

    // ---- Phase 4: append grows the universe and keeps deletes ----
    info!(run_id = %run_id, phase = 4, "phase 4: append grows universe preserving delete mask and tail clearing");
    let v_before = table.read().unwrap().version_info().version;
    {
        let extra: Vec<serde_json::Map<String, Value>> = vec![
            {
                let mut m = serde_json::Map::new();
                m.insert("city".into(), json!("Shenzhen"));
                m.insert("age".into(), json!(50));
                m.insert("active".into(), Value::Null);
                m
            },
            {
                let mut m = serde_json::Map::new();
                m.insert("city".into(), Value::Null);
                m.insert("age".into(), json!(40));
                m.insert("active".into(), json!(true));
                m
            },
        ];
        let mut t = table.write().unwrap();
        let info = t.append(&extra).unwrap();
        assert_eq!(info.version, v_before + 1);
        assert_eq!(info.total_rows, 15, "13 + 2");
        assert_eq!(info.deleted_rows, 3, "old deletes survive append");
        // Rows 0,3,7 remain deleted after growth.
        assert!(t.deleted_bitmap().get(0));
        assert!(t.deleted_bitmap().get(3));
        assert!(t.deleted_bitmap().get(7));
        assert!(!t.deleted_bitmap().get(13));
    }
    {
        let t = table.read().unwrap();
        let result = tribool_index::query::run(
            &t,
            &Expr::Cmp {
                column: "age".into(),
                cmp: "=".into(),
                value: Some(tribool_index::index::Literal::Int(40)),
            },
            &run_id,
        )
        .unwrap();
        // New row 14 has age 40 and is alive; row 7 (deleted, age 40) is excluded.
        assert_eq!(result.matched_ids(), vec![2, 4, 10, 11, 14]);
        // row 13 age NULL-ish? It is 50 -> FALSE. New NULL city irrelevant here.
        assert_eq!(result.tris.count_unknown(), 3, "rows 1,5,9 still NULL age");
        info!(run_id = %run_id, matched = ?result.matched_ids(), "post-append concrete assertion");
    }

    // ---- Tail-byte assertion on the raw bitmap representation ----
    {
        let t = table.read().unwrap();
        let alive = t.alive();
        assert_eq!(alive.len(), 15, "universe 15 -> 2 bytes, top bit invalid");
        let bytes = alive.as_bytes();
        assert_eq!(bytes.len(), 2);
        assert_eq!(bytes[1] & 0b1000_0000, 0, "invalid tail bit must be zero");
    }

    if failures.is_empty() {
        info!(run_id = %run_id, "ALL VERIFICATION CHECKS PASSED");
        println!("VERIFY PASSED (run_id={run_id})");
        ExitCode::SUCCESS
    } else {
        for f in &failures {
            warn!(run_id = %run_id, failure = %f, "verification failure");
        }
        eprintln!("VERIFY FAILED: {} discrepancy/ies", failures.len());
        for f in &failures {
            eprintln!("  - {f}");
        }
        ExitCode::FAILURE
    }
}
